import pathlib
p = pathlib.Path('src/codegen/lower_inst/builtins/io/filesystem_ops.rs')
s = p.read_text()
old = '''    let Some(literal) = optional_const_string_operand(ctx, source)? else {
        return Ok(false);
    };'''
new = '''    let Some(literal) = optional_const_string_operand(ctx, source)? else {
        // A RUN-TIME path takes this route too. The comment above used to claim the runtime
        // reached these schemes on its own; measured, it does not: `__rt_copy` reads through
        // `__rt_file_get_contents`, whose runtime half knows registered wrappers and NOT
        // `php://filter/`, so `copy('php://filter/read=string.rot13/resource=' . $f, $d)` failed
        // to open where `fopen()` and `file_get_contents()` on the very same string succeed.
        return Ok(true);
    };'''
assert s.count(old) == 1
s = s.replace(old, new)
p.write_text(s)
print('routed dynamic sources through the lowered path')
